('69','4','Zendesk','','','','','','','','25','0','0','0','0','1','3','10s','1','const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\nvar Zendesk = {\r\n	params: {},\r\n\r\n	setParams: function (params) {\r\n		if (typeof params !== \'object\') {\r\n			return;\r\n		}\r\n\r\n		Zendesk.params = params;\r\n		if (typeof Zendesk.params.url === \'string\') {\r\n			if (!Zendesk.params.url.endsWith(\'/\')) {\r\n				Zendesk.params.url += \'/\';\r\n			}\r\n			Zendesk.params.url += \'api/v2/\';\r\n		}\r\n	},\r\n\r\n	addCustomFields: function (data, fields) {\r\n		if (typeof fields === \'object\' && Object.keys(fields).length) {\r\n			var schema = Zendesk.getSchema(),\r\n				arr = [],\r\n				i,\r\n				n;\r\n\r\n			if (schema) {\r\n				Object.keys(fields)\r\n					.forEach(function(field) {\r\n						for (i = 0, n = schema.ticket_fields.length; i < n; i++) {\r\n							if (schema.ticket_fields[i].id == field\r\n								&& [\'text\', \'integer\', \'date\'].indexOf(schema.ticket_fields[i].type) !== -1){\r\n\r\n								switch (schema.ticket_fields[i].type) {\r\n									case \'integer\':\r\n										fields[field] = parseInt(fields[field]);\r\n										break;\r\n									case \'date\':\r\n										if (fields[field].match(/^\\d{4}[.-]\\d{2}[.-]\\d{2}$/) !== null) {\r\n						