('32783','21','','10365','Get tokens','vault.get_tokens','15m','0','0','0','4','','','','',NULL,NULL,'const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\nvar params = JSON.parse(value);\r\n\r\nparams[\'url\'] = params.scheme + \'://\'\r\n	+ params.host + \':\'\r\n	+ params.port + \'/v1/auth/token/lookup-accessor\';\r\n\r\nvar tls = new CTlsConfig(params.tls_verify);\r\ntls.checkURL(params.url);\r\n\r\nvar request = new HttpRequest(tls.options),\r\n	output = [];\r\n\r\nrequest.addHeader(\'X-Vault-Token: \' + params.token);\r\n\r\nparams.accessors.trim().split(/\\x20+/).forEach(function (accessor) {\r\n	if (!accessor) {\r\n		return;\r\n	}\r\n\r\n	var response,\r\n		data = {},\r\n		error_msg = \'\';\r\n\r\n	try {\r\n		response = request.post(params.url, JSON.stringify({ accessor: accessor }));\r\n		Zabbix.log(4, \'[ Vault API ] Received response with status code \' + request.getStatus() + \': \' + response);\r\n\r\n		if (response !== null) {\r\n			try {\r\n				response = JSON.parse(response);\r\n			}\r\n			catch (error) {\r\n				throw \'Failed to parse response received from Vault API. Check debug log for more information.\';\r\n			}\r\n		}\r\n\r\n		if (request.getStatus() !== 200) {\r\n			throw response.errors && response.errors[0] || JSON.stringify(response);\r\n		}\r\n\r\n		if (typeof response !== \'object\' || typeof response.data === \'undefined\') {\r\n			throw \'Cannot lookup token from Vault API. Check debug log for more information.\';\r\n		}\r\n\r\n		data = response.data;\r\n	}\r\n	catch (error) {\r\n		error_msg = error;\r\n	}\r\n\r\n	output.push({\r\n		\'accessor\': accessor,\r\n		\'token_name\': data.display_name || \'null\',\r\n		\'ttl\': data.ttl || 0,\r\n		\'has_ttl\': !!data.expire_time,\r\n		\'error\': error_msg.toString()\r\n	});\r\n});\r\n\r\nreturn JSON.stringify(output);','','0','','','','','0',NULL,'Get information about tokens via their accessors. Accessors are defined in the macro "{$VAULT.TOKEN.ACCESSORS}".','0','30d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','e8cb015d45ad4e3b9f87d3cbbae3a980','0','2','0'),
