('34065','20','get[1.3.6.1.4.1.9.9.13.1.3.1.6.{#SNMPINDEX}]','10392','{#SNMPVALUE}: Temperature status','sensor.temp.status[{#SNMPINDEX}]','1m','31d','365d','0','3','','','','',NULL,'242','','','0','','','','','2',NULL,'MIB: CISCO-ENVMON-MIB\r\nObject name: ciscoEnvMonTemperatureState\r\nThe current state of the test point being instrumented.','0','30d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','e1636ece86b1427cad01e7223052b526','0','2','0'),
