('34272','15','','10396','{#VOLUMENAME}: Volume latency, total','netapp.volume.statistics.latency.total[{#VOLUMENAME}]','1m','31d','365d','0','0','','!ms','','',NULL,NULL,'(last(//netapp.volume.statistics.latency_raw.total[{#VOLUMENAME}]) - last(//netapp.volume.statistics.latency_raw.total[{#VOLUMENAME}],#2)) /\r\n(last(//netapp.volume.statistics.iops_raw.total[{#VOLUMENAME}]) - last(//netapp.volume.statistics.iops_raw.total[{#VOLUMENAME}],#2) +\r\n(last(//netapp.volume.statistics.iops_raw.total[{#VOLUMENAME}]) - last(//netapp.volume.statistics.iops_raw.total[{#VOLUMENAME}],#2) = 0) ) * 0.001','','0','','','','','2',NULL,'The average latency per I/O operation in milliseconds observed at the storage object. Performance metric aggregated over all types of I/O operations.','0','30d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','ff804a090b064bfeb60183d7d7d2abe1','0','2','0'),
