('39743','21','','10503','Get data','velocloud.get','{$VELOCLOUD.SDWAN.FREQUENCY}','0','0','0','4','','','','',NULL,NULL,'const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\nvar VeloCloud = {\r\n	params: {},\r\n\r\n	setParams: function (params) {\r\n		[\'url\', \'token\'].forEach(function (field) {\r\n			if (typeof params !== \'object\' || typeof params[field] === \'undefined\' || params[field] === \'\') {\r\n				throw \'Required param is not set: \' + field + \'.\';\r\n			}\r\n		});\r\n\r\n		VeloCloud.params = params;\r\n\r\n		if (VeloCloud.params.token === \'{\' + \'$VELOCLOUD.TOKEN}\') {\r\n			throw \'Please change {\' + \'$VELOCLOUD.TOKEN} macro with the proper value.\';\r\n		}\r\n		if (!VeloCloud.params.url.startsWith(\'http://\') && !VeloCloud.params.url.startsWith(\'https://\')) {\r\n			VeloCloud.params.url = \'https://\' + params.url;\r\n		}\r\n		if (!VeloCloud.params.url.endsWith(\'/\')) {\r\n			VeloCloud.params.url += \'/\';\r\n		}\r\n\r\n		VeloCloud.tls = new CTlsConfig(params.tls_verify);\r\n		VeloCloud.tls.checkURL(VeloCloud.params.url);\r\n	},\r\n\r\n	getField: function (data, path, trace) {\r\n		const steps = path.split(\'.\');\r\n\r\n		for (var i = 0; i < steps.length; i++) {\r\n			var step = steps[i];\r\n			if (typeof data !== \'object\' 