('42724','21','','10516','Get data','openweathermap.get.data','10m','0','0','0','4','','','','',NULL,NULL,'const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\nvar params = JSON.parse(value),\r\n	tls = new CTlsConfig(params.tls_verify),\r\n	request = new HttpRequest(tls.options),\r\n	data = [],\r\n	error_msg = [],\r\n	measurement,\r\n	temp_unit,\r\n	wind_unit,\r\n	errors_only = [],\r\n	error_locations = [],\r\n	unique_errors,\r\n	new_error_msg;\r\n\r\nfunction getHttpData(query) {\r\n	url = tls.checkURL(params.api_endpoint + query) + \'&appid=\' + params.apikey + \'&units=\' + params.units + \'&lang=\' + params.lang;\r\n	response = request.get(url);\r\n	Zabbix.log(4, \'[ Openweathermap ] [ \' + url + \' ] Received response with status code \' + request.getStatus() + \': \' + response);\r\n\r\n	if (response !== null) {\r\n		try {\r\n			response = JSON.parse(response);\r\n		}\r\n		catch (error) {\r\n			throw \'Failed to parse response.\';\r\n		}\r\n	}\r\n\r\n	if (request.getStatus() !== 200) {\r\n		if (response.error && response.error.message) {\r\n			throw response.error.message;\r\n		}\r\n		else {\r\n			throw \'Failed to receive data. Invalid response status code: \' + request.getStatus();\r\n		}\r\n	}\r\n	return response;\r\n}\r\n\r\nswitch (params.units) {\r\n	case \'metric\':\r\n		measurement = \'metric\';\r\n		temp_unit = \'C\';\r\n		wind_unit = \'meter/sec\';\r\n		break;\r\n	case \'imperial\':\r\n		measurement = \'imperial\';\r\n		temp_unit = \'F\';\r\n		wind_unit = \'miles/hour\';\r\n		break;\r\n	default:\r\n		measurement = \'standard\';\r\n		temp_unit = \'K\';\r\n		wind_unit = \'meter/sec\';\r\n}\r\n\r\nlocations = params.location.split(\'|\');\r\nfor (var i in locations) {\r\n	try {\r\n		if (/^[0-9]+$/g.test(locations[i])) {\r\n			result = getHttpData(\'id=\' + locations[i]);\r\n		}\r\n		else if (/^.*,[\\w]+$/g.test(locations[i])) {\r\n			result = getHttpData(\'zip=\' + locations[i]);\r\n		}\r\n		else if (/^(\\-)?[0-9]{1,2}(\\.[0-9]+)?,(\\-)?[0-9]{1,2}(\\.[0-9]+)?/g.test(locations[i])) {\r\n			coordinates = locations[i].split(\',\');\r\n			result = getHttpData(\'lat=\' + coordinates[0] + \'&lon=\' + coordinates[1]);\r\n		}\r\n		else {\r\n			result = getHttpData(\'q=\' + encodeURIComponent(locations[i]));\r\n		}\r\n		if (!data.filter(function (location) { return location.id === result.id; }).length) {\r\n			result.measurement = measurement;\r\n			result.temp_unit = temp_unit;\r\n			result.wind_unit = wind_unit;\r\n			data.push(result);\r\n		}\r\n	} catch (error) {\r\n		errors = {};\r\n		errors.location = locations[i];\r\n		errors.error = error.toString();\r\n		error_msg.push(errors);\r\n		errors_only.push(error.toString());\r\n	}\r\n}\r\n\r\nif (error_msg.length === 0) {\r\n	return JSON.stringify({\r\n		\'data\': data,\r\n		\'errors\': error_msg.toString()\r\n	});\r\n} else {\r\n	unique_errors = errors_only.filter(function (value, index, self) {\r\n		return self.indexOf(value) == index;\r\n	});\r\n\r\n	if (unique_errors.length === 1) {\r\n		for (var j in error_msg) {\r\n			error_locations.push(error_msg[j].location);\r\n		}\r\n		new_error_msg = \'Failed to retrieve data for the following locations: \' + error_locations + \'. \' + unique_errors[0];\r\n		return JSON.stringify({\r\n			\'data\': data,\r\n			\'errors\': new_error_msg\r\n		});\r\n	} else {\r\n		return JSON.stringify({\r\n			\'data\': data,\r\n			\'errors\': error_msg\r\n		});\r\n	}\r\n}','','0','','','','','0',NULL,'JSON array with result of OpenWeatherMap API requests.','0','30d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','7db240f752294b2eb86537d6c06cac5e','0','2','0'),
('42738','21','','10517','API service status','proxmox.api.available','5m','31d','365d','0','3','','','','',NULL,'954','const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\ntry {\r\n  var params = JSON.parse(value);\r\n  var tls = new CTlsConfig(params.tls_verify);\r\n  var req = new HttpRequest(tls.options);\r\n  req.addHeader(\'Authorization: PVEAPIToken=\' + params.token + \'=\' + params.secret);\r\n  req.get(encodeURI(\'https://\' + params.url + \':\' + params.port + \'/api2/json/version\'));\r\n} catch (error) {\r\n	Zabbix.log(3, "Proxmox API failed: " + params.url + " Error: " + error);\r\n	if (!Number.isInteger(error))\r\n		return 520;\r\n}\r\nreturn req.getStatus();','','0','','','','','0',NULL,'Get API service status.','0','30d','0','',NULL,'10s','','','','200','1','0','','','0','0','0','0','0','0','0','75f8f8c507774f529ade4bc4255f5fd2','0','2','0'),
