('45605','21','','10587','Get tenants','openstack.nova.tenant.get','{$OPENSTACK.NOVA.INTERVAL.TENANTS}','0','0','0','4','','','','',NULL,NULL,'const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\n\r\nconst request_path = \'/os-simple-tenant-usage\';\r\n\r\nfunction checkParams(params) {\r\n	[\'api_url\', \'api_token\', \'period\'].forEach(function (field) {\r\n		if (typeof params !== \'object\' || typeof params[field] === \'undefined\' || params[field] === \'\') {\r\n			throw \'Required param is not set: \' + field + \'.\';\r\n		}\r\n		if (field === \'period\') {\r\n			const supported_values = [\'y\', \'m\', \'w\', \'d\']\r\n			if (supported_values.indexOf(params[field]) === -1) {\r\n				throw \'Tenant period not correctly set. Expected one of "y", "m", "w", "d"; received: \' + field + \'.\';\r\n			}\r\n		}\r\n	});\r\n	return params;\r\n}\r\n\r\nfunction buildUrl(url, period) {\r\n	const current_date = new Date();\r\n	var datetime_formatted = \'\'\r\n	switch (period) {\r\n		case \'y\':\r\n			datetime_formatted =\r\n				current_date.getFullYear() + \'-\' +\r\n				\'1-\' +\r\n				\'1T\' +\r\n				\'00:00:00\'\r\n			break;\r\n		case \'m\':\r\n			datetime_formatted =\r\n			current_date.getFullYear() + \'-\' +\r\n				(current_date.getMonth() + 1) + \'-\' +\r\n			\'1T\' +\r\n			\'00:00:00\'\r\n			break;\r\n		case \'w\':\r\n			const first_date_of_week = current_date.getDate() - current_date.getDay() + 1\r\n			datetime_formatted =\r\n				current_date.getFullYear() + \'-\' +\r\n				(current_date.getMonth() + 1) + \'-\' +\r\n				first_date_of_week + \'T\' +\r\n				\'00:00:00\'\r\n			break;\r\n		case \'d\':\r\n			datetime_formatted =\r\n				current_date.getFullYear() + \'-\' +\r\n				(current_date.getMonth() + 1) + \'-\' +\r\n				current_date.getDate() + \'T\' +\r\n				\'00:00:00\'\r\n			break;\r\n	}\r\n\r\n	return url + request_path + \'?\' +\r\n		\'start=\' + encodeURIComponent(datetime_formatted)\r\n}\r\n\r\nfunction getHttpData(url, params, api_token) {\r\n	const request = new HttpRequest(tls.options);\r\n\r\n	request.addHeader(\'Content-Type: application/json\');\r\n	request.addHeader(\'X-Auth-Token: \' + api_token);\r\n	if (params[\'http_proxy\']) {\r\n		request.setProxy(params[\'http_proxy\'])\r\n		Zabbix.log(4, \'[ Openstack Nova API ] Using http proxy: \' + params[\'http_proxy\']);\r\n	}\r\n\r\n	const response = request.get(url, JSON.stringify(params));\r\n	Zabbix.log(4, \'[ Openstack Nova API ] [ \' + url + \' ] Received response with status code \' + request.getStatus() + \': \' + response);\r\n\r\n	if (request.getStatus() !== 200) {\r\n		if (typeof (response.error && response.error.message) !== \'undefined\') {\r\n			throw response.error.message;\r\n		} else {\r\n			throw \'Failed to receive data: invalid response status code ( \' + request.getStatus() + \' ). Check debug log for more information.\';\r\n		}\r\n	}\r\n\r\n	return response;\r\n}\r\n\r\nconst params = checkParams(JSON.parse(value)),\r\n	url = params.api_url,\r\n	token = params.api_token,\r\n	period = params.period;\r\n\r\nconst tls = new CTlsConfig(params.tls_verify);\r\ntls.checkURL(url);\r\n\r\nreturn getHttpData(buildUrl(url, period), params, token);','','0','','','','','0',NULL,'Gets a list of tenants and its data.','0','30d','0','',NULL,'10s','','','','200','1','0','','','0','0','0','0','0','0','0','c258e567922c4f71a4dee9c0d6b88b1e','0','2','0'),
