('45700','11','','10589','DB [{#DBNAME}]: Bloating tables','db.odbc.select[pgsql.db.bloating_tables,,"Database={#DBNAME};{$PG.CONNSTRING.ODBC}"]','1m','31d','365d','0','3','','','','',NULL,NULL,'SELECT count(*)\r\nFROM pg_catalog.pg_stat_all_tables\r\nWHERE (n_dead_tup/(n_live_tup+n_dead_tup)::float8) > 0.2\r\n  AND (n_live_tup+n_dead_tup) > 50','','0','{$PG.USER}','{$PG.PASSWORD}','','','2',NULL,'Number of bloating tables.','0','30d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','cb7067b756bc4b3eb5be2ee2361df6f8','0','2','0'),
('45701','11','','10589','DB [{#DBNAME}]: Database size','db.odbc.select[pgsql.db.size,,"Database={#DBNAME};{$PG.CONNSTRING.ODBC}"]','5m','31d','365d','0','3','','B','','',NULL,NULL,'SELECT pg_database_size(current_database())','','0','{$PG.USER}','{$PG.PASSWORD}','','','2',NULL,'Database size.','0','30d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','f6bc4dd7f66a4a399a16230b6a7a8f2d','0','2','0'),
('45743','21','','10590','Authentication','sd_wan.authentication','{$SDWAN.AUTH.FREQUENCY}','0','0','0','4','','','','',NULL,NULL,'const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\nvar params = JSON.parse(value),\r\n	tls = new CTlsConfig(params.tls_verify),\r\n	request = new HttpRequest(tls.options),\r\n	cookies = [],\r\n	token = "",\r\n	error_msg = "";\r\n\r\nfunction authenticate(url) {\r\n	tls.checkURL(url);\r\n	var payload = \'j_username=\' + encodeURIComponent(params.username)\r\n		+ \'&j_password=\' + encodeURIComponent(params.password);\r\n	request.addHeader(\'Content-Type\', \'application/x-www-form-urlencoded\');\r\n	response = request.post(url, payload);\r\n	Zabbix.log(4, \'[ SD-WAN API ] [ \' + url + \' ] Received response with status code \' + request.getStatus() + \': \' + response);\r\n\r\n	if (request.getStatus() !== 200) {\r\n		throw \'Failed to receive data: invalid response status code.\';\r\n	}\r\n\r\n	if (response !== null && response != "") {\r\n		throw \'Authentication failed.\';\r\n	}\r\n\r\n	var headers = request.getHeaders();\r\n	for (key in headers) {\r\n		if (key.toLowerCase() == \'set-cookie\') {\r\n			var entries = headers[key].split(\',\');\r\n			for (idx in entries) {\r\n				var value = entries[idx].split(\';\')[0];\r\n				cookies.push(value);\r\n			}\r\n		}\r\n	}\r\n};\r\n\r\nfunction getToken(url) {\r\n	tls.checkURL(url);\r\n	response = request.get(url);\r\n	Zabbix.log(4, \'[ SD-WAN API ] [ \' + url + \' ] Received response with status code \' + request.getStatus() + \': \' + response);\r\n\r\n	if (request.getStatus() !== 200) {\r\n		throw \'Failed to receive data: invalid response status code.\';\r\n	}\r\n\r\n	var headers = request.getHeaders();\r\n	for (key in headers) {\r\n		if (key.toLowerCase() == \'content-type\' && headers[key] != \'application/json\') {\r\n			throw \'Something went wrong while getting the authentication token. Check debug log for more information.\';\r\n		}\r\n	}\r\n\r\n	return response;\r\n};\r\n\r\ntry {\r\n\r\n	[\'username\', \'password\', \'url\'].forEach(function (field) {\r\n		var macro = \'{$SDWAN.API.\' + field.toUpperCase() + \'}\';\r\n		if (params[field] === macro || params[field] === \'\') {\r\n			throw \'Please change \' + macro + \' macro to the proper value.\';\r\n		}\r\n		if (typeof params[field] === \'undefined\') {\r\n			throw \'Please set \\\'\' + field + \'\\\' script input parameter to \' + macro + \' macro value.\';\r\n		}\r\n	});\r\n\r\n	if (params.url.indexOf(\'http://\') === -1 && params.url.indexOf(\'https://\') === -1) {\r\n		params.url = \'https://\' + params.url;\r\n	}\r\n\r\n	if (!params.url.endsWith(\'/\')) {\r\n		params.url += \'/\';\r\n	}\r\n\r\n	if (typeof params.http_proxy !== \'undefined\' && params.http_proxy !== \'{\' + \'$SDWAN.HTTP_PROXY}\' && params.http_proxy !== \'\') {\r\n		request.setProxy(params.http_proxy);\r\n	}\r\n\r\n	authenticate(params.url + \'j_security_check\');\r\n	token = getToken(params.url + \'dataservice/client/token\');\r\n\r\n} catch (err) {\r\n	error_msg = err;\r\n};\r\n\r\nreturn JSON.stringify({\r\n	\'cookie\': cookies.join(\'; \'),\r\n	\'token\': token,\r\n	\'error\': error_msg.toString()\r\n});','','0','','','','','0',NULL,'Cisco SD-WAN authentication with service account parameters and temporary-generated token usage.\r\nReturns an authentication token and session id; it is required only once and is used for all dependent script items.\r\nA session will expire after 30 minutes of inactivity or after 24 hours, which is the total lifespan of a session.\r\nCheck the template documentation for the details.','0','30d','0','',NULL,'{$SDWAN.DATA.TIMEOUT}','','','','200','1','0','','','0','0','0','0','0','0','0','5aa5a643a3cf42148454507da22aeb17','0','2','0'),
