('49865','21','','10665','Get data','azure.vault.data.get','1m','0','0','0','4','','','','',NULL,NULL,'const CTlsConfig = function (raw_value) {\r\n	raw_value = String(raw_value).trim().toLowerCase();\r\n\r\n	if ([\'none\', \'peer\', \'full\'].indexOf(raw_value) === -1) {\r\n		raw_value = \'full\';\r\n	}\r\n\r\n	this.options = {\r\n		SSLVerifyPeer: (raw_value === \'peer\' || raw_value === \'full\'),\r\n		SSLVerifyHost: (raw_value === \'full\')\r\n	};\r\n\r\n	this.enabled = (raw_value !== \'none\');\r\n\r\n	this.checkURL = function (url) {\r\n		if (this.enabled && !/^https:\\/\\//i.test(url)) {\r\n			throw \'TLS certificate verification is enabled by {$\' + \'HTTP.TLS.VERIFY}, but the URL uses plain HTTP: \' + url +\r\n			\'. Use an "https://" URL, or set {$\' + \'HTTP.TLS.VERIFY} to `none` to disable verification.\';\r\n		}\r\n\r\n		return url;\r\n	};\r\n}\r\n\r\n\r\nvar Azure = {\r\n	params: {},\r\n	token: null,\r\n\r\n	setParams: function (params) {\r\n		[\'app_id\', \'password\', \'tenant_id\', \'subscription_id\', \'resource_id\', \'period\'].forEach(function (field) {\r\n			if (typeof params !== \'object\' || typeof params[field] === \'undefined\' || params[field] === \'\') {\r\n				throw \'Required param is not set: \' + field + \'.\';\r\n			}\r\n		});\r\n\r\n		Azure.params = params;\r\n		Azure.tls = new CTlsConfig(params.tls_verify);\r\n	},\r\n\r\n	login: function () {\r\n		var response, login = new HttpRequest(Azure.tls.options);\r\n\r\n		if (typeof Azure.params.proxy !== \'undefined\' && Azure.params.proxy !== \'\') {\r\n			login.setProxy(Azure.params.proxy);\r\n		}\r\n\r\n		login.addHeader(\'Content-Type: application/x-www-form-urlencoded\');\r\n		response = login.post(\r\n			\'https://login.microsoftonline.com/\' + encodeURIComponent(Azure.params.tenant_id) + \'/oauth2/token\',\r\n			\'grant_type=client_credentials&resource=\' + encodeURIComponent(\'https://management.azure.com/\') + \'&client_id=\' + encodeURIComponent(Azure.params.app_id) + \'&client_secret=\' + encodeURIComponent(Azure.params.password)\r\n		);\r\n\r\n		if (login.getStatus() !== 200) {\r\n			throw \'Login failed with status code \' + login.getStatus() + \': \' + response;\r\n		}\r\n\r\n		try {\r\n			response = JSON.parse(response);\r\n		}\r\n		catch (error) {\r\n			throw \'Failed to parse login session response.\';\r\n		}\r\n\r\n		if (!response.hasOwnProperty(\'access_token\')) {\r\n			throw \'Authentication response does not contain access token.\';\r\n		}\r\n\r\n		Azure.token = response[\'access_token\'];\r\n	},\r\n\r\n	request: function (url) {\r\n		var response, request = new HttpRequest(Azure.tls.options);\r\n\r\n		if (typeof Azure.params.proxy !== \'undefined\' && Azure.params.proxy !== \'\') {\r\n			request.setProxy(Azure.params.proxy);\r\n		}\r\n\r\n		if (!Azure.token) {\r\n			throw \'Request does not contain access token.\';\r\n		}\r\n\r\n		request.addHeader(\'Content-Type: application/json\');\r\n		request.addHeader(\'Authorization: Bearer \' + Azure.token);\r\n		Zabbix.log(4, \'[ Azure Vault ] request url: \' + url);\r\n\r\n		response = request.get(url);\r\n\r\n		if (request.getStatus() !== 200) {\r\n			throw \'Request failed with status code \' + request.getStatus() + \': \' + response;\r\n		}\r\n\r\n		try {\r\n			return JSON.parse(response);\r\n		}\r\n		catch (error) {\r\n			throw \'Failed to parse response received from API.\';\r\n		}\r\n	},\r\n\r\n	getField: function (data, path) {\r\n		var steps = path.split(\'.\');\r\n\r\n		for (var i = 0; i < steps.length; i++) {\r\n			var step = steps[i];\r\n			if (typeof data !== \'object\' || typeof data[step] === \'undefined\') {\r\n				throw \'Required field was not found: \' + path;\r\n			}\r\n			data = data[step];\r\n		}\r\n\r\n		return data;\r\n	},\r\n\r\n	getMetricsData: function () {\r\n		var data = {},\r\n			end_date = new Date(),\r\n			start_date = new Date();\r\n\r\n		function formatDate(date) {\r\n			var year = date.getFullYear(),\r\n				month = (date.getMonth() + 1),\r\n				day = date.getDate(),\r\n				hours = date.getHours(),\r\n				minutes = date.getMinutes(),\r\n				seconds = date.getSeconds(),\r\n				ampm = hours >= 12 ? \'PM\' : \'AM\';\r\n\r\n			hours = hours % 12 || 12;\r\n			month = month < 10 ? \'0\' + month : month;\r\n			day = day < 10 ? \'0\' + day : day;\r\n			hours = hours < 10 ? \'0\' + hours : hours;\r\n			minutes = minutes < 10 ? \'0\' + minutes : minutes;\r\n			seconds = seconds < 10 ? \'0\' + seconds : seconds;\r\n\r\n			formatted_date = year + \'-\' + month + \'-\' + day + \' \' + hours + \':\' + minutes + \':\' + seconds + \' \' + ampm;\r\n\r\n			return formatted_date\r\n		};\r\n\r\n		start_date.setDate(start_date.getDate() - Azure.params.period);\r\n		end_date = encodeURIComponent(\'\\\'\' + formatDate(end_date) + \'\\\'\');\r\n		start_date = encodeURIComponent(\'\\\'\' + formatDate(start_date) + \'\\\'\');\r\n		date_filter = \'&$filter=\' + encodeURIComponent(\'startTime eq \') + start_date + encodeURIComponent(\' and endTime eq \') + end_date;\r\n\r\n		data.health = Azure.getField(Azure.request(\'https://management.azure.com\' + Azure.params.resource_id + \'/providers/Microsoft.ResourceHealth/availabilityStatuses?api-version=2020-05-01\'), \'value.0.properties\');\r\n		data.jobs = Azure.getField(Azure.request(\'https://management.azure.com\' + Azure.params.resource_id + \'/backupjobs?api-version=2025-01-01\' + date_filter), \'value\');\r\n\r\n		return data\r\n	}\r\n};\r\n\r\ntry {\r\n	Azure.setParams(JSON.parse(value));\r\n	Azure.login();\r\n	return JSON.stringify(Azure.getMetricsData());\r\n}\r\ncatch (error) {\r\n	error += (String(error).endsWith(\'.\')) ? \'\' : \'.\';\r\n	Zabbix.log(3, \'[ Azure Vault ] ERROR: \' + error);\r\n	return JSON.stringify({ \'error\': error });\r\n}','','0','','','','','0',NULL,'Gathers data of the Azure vault.','0','7d','0','',NULL,'{$AZURE.DATA.TIMEOUT}','','','','200','1','0','','','0','0','0','0','0','0','0','57d191150c06423daa1674d09c846dc7','0','2','0'),
