('17081','{20086} > {$MSSQL.PERCENT_COMPILATIONS.MAX}','MSSQL: Percent of ad hoc queries running is high','','0','2','The lower this value is, the better. High values often indicate excessive ad hoc querying and should be as low as possible. If excessive ad hoc querying is happening, try rewriting the queries as procedures or invoke the queries using `sp_executeSQL`. When rewriting isn\'t possible, consider using a plan guide or setting the database to parameterization forced mode.',NULL,'0','0','0','','0','','0','','0','MSSQL: Percent of ad hoc queries running is over {$MSSQL.PERCENT_COMPILATIONS.MAX}% for 15m','c5c1840220cd44fcaa7b47e0d52309bb',''),
('17082','{20087} > {$MSSQL.PERCENT_RECOMPILATIONS.MAX}','MSSQL: Percent of times statement recompiles is high','','0','2','This number should be at or near zero, since recompiles can cause deadlocks and exclusive compile locks. This counter\'s value should follow in proportion to "Batch Requests/sec" and "SQL Compilations/sec".',NULL,'0','0','0','','0','','0','','0','MSSQL: Percent of times statement recompiles is over {$MSSQL.PERCENT_RECOMPILATIONS.MAX}% for 15m','d5bad8ead8704e00bf332032e22ebfdd',''),
('17083','{20088} > 0.001','MSSQL: Number of index and table scans exceeds index searches in the last 15m','','0','2','Index searches are preferable to index and table scans. For OLTP applications, optimize for more index searches and less scans (preferably, 1 full scan for every 1000 index searches). Index and table scans are expensive I/O operations.',NULL,'0','0','0','','0','','0','','0','','3c22a74a94d641389b57a6013ddd10cb',''),
('17084','{20089}=0','MSSQL: Service is unavailable','','0','5','The TCP port of the MSSQL Server service is currently unavailable.',NULL,'0','0','0','','0','','0','','0','','152af5cc3ce04d4aa8ab255c37aed6c6',''),
('17088','{20096}<>"running-ap"','MikroTik: Interface {#IFNAME}({#IFALIAS}): AP interface {#IFNAME}({#IFALIAS}) is not running','','0','2','Access point interface can be not running by different reasons - disabled interface, power off, network link down.',NULL,'0','2','0','','0','','0','','0','','e4aedbd5e0c64cf48831bf08192e19bf',''),
('17089','{28360} > {$PHP_FPM.QUEUE.WARN.MAX}','PHP-FPM: Queue utilization is high','','0','2','The queue for this pool has reached `{$PHP_FPM.QUEUE.WARN.MAX}%` of its maximum capacity. \r\nItems in the queue represent the current number of connections that have been initiated on this pool but not yet accepted.',NULL,'0','0','0','','0','','0','','0','PHP-FPM: Queue utilization is high (over {$PHP_FPM.QUEUE.WARN.MAX}% for 15m)','a11264f0e1174b7fb81b457dad1a745f',''),
