('23929','{34134}<0 and {34135}>0\r\nand (\r\n{34136}=6 or\r\n{34136}=7 or\r\n{34136}=11 or\r\n{34136}=62 or\r\n{34136}=69 or\r\n{34136}=117\r\n)\r\nand\r\n({34137}<>2)','Juniper MX: Interface [{#IFNAME}][{#IFALIAS}]: Ethernet has changed to lower speed than it was before','','0','1','This Ethernet connection has transitioned down from its known maximum speed. This might be a sign of autonegotiation issues. Acknowledge to close the problem manually.',NULL,'0','2','1','({34134}>0 and {34138}>0) or\r\n({34137}=2)','0','','1','Current reported speed: {ITEM.LASTVALUE1}','0','','140de6180ae64aeab26d898518392c54',''),
