('25128','({35941}>({$IF.UTIL.MAX:"{#IFNAME}"}/100)*{35942} or\r\n{35943}>({$IF.UTIL.MAX:"{#IFNAME}"}/100)*{35942}) and\r\n{35942}>0','Vyatta: Interface [{#IFNAME}][{#IFALIAS}]: High bandwidth usage','','0','2','The utilization of the network interface is close to its estimated maximum bandwidth.',NULL,'0','2','1','{35941}<(({$IF.UTIL.MAX:"{#IFNAME}"}-3)/100)*{35942} and\r\n{35943}<(({$IF.UTIL.MAX:"{#IFNAME}"}-3)/100)*{35942}','0','','1','In: {ITEM.LASTVALUE1}, out: {ITEM.LASTVALUE3}, speed: {ITEM.LASTVALUE2}','0','Vyatta: Interface [{#IFNAME}][{#IFALIAS}]: High bandwidth usage (>{$IF.UTIL.MAX:"{#IFNAME}"}%)','0cf252aaa8bf429c9c9c7340e8d83d0d',''),
