('101285','48321','2','21','var inArray = JSON.parse(value);\nvar afiSafiMap = {\n	\'1.1\': \'IPv4 unicast\',\n	\'1.2\': \'IPv4 multicast\',\n	\'2.1\': \'IPv6 unicast\',\n	\'2.2\': \'IPv6 multicast\',\n	\'25.65\': \'BGP-VPLS/BGP-L2VPN\',\n	\'1.128\': \'L3VPN IPv4 unicast\',\n	\'1.129\': \'L3VPN IPv4 multicast\',\n	\'2.128\': \'L3VPN IPv6 unicast\',\n	\'2.129\': \'L3VPN IPv6 multicast\',\n	\'1.132\': \'RT-Constrain\',\n	\'1.133\': \'Flow-spec\',\n	\'1.134\': \'Flow-spec\',\n	\'3.128\': \'CLNS VPN\',\n	\'1.5\': \'NG-MVPN IPv4\',\n	\'2.5\': \'NG-MVPN IPv6\',\n	\'1.66\': \'MDT-SAFI\',\n	\'1.4\': \'labeled IPv4\',\n	\'2.4\': \'labeled IPv6 (6PE)\'\n};\n\nvar outArr = [];\ninArray.forEach(function (item) {\n	item[\'{#BGPM2_AFI_SAFI}\'] = afiSafiMap[item[\'{#SNMPINDEX}\'].slice(2)] === undefined ? "" : afiSafiMap[item[\'{#SNMPINDEX}\'].slice(2)];\n	outArr.push(item)\n});\nreturn JSON.stringify(outArr);','0',''),
